  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'يتحدث النص عن الطاقة من حيث:', '["مصادرها", "استهلاكها", "استخداماتها", "تنوعها"]'::jsonb, 1, 'الجملة الافتتاحية «زاد استهلاك الطاقة بشكل كبير» هي الفكرة المحورية، وما ذُكر بعدها عن المصادر والاستخدامات جاء تفصيلاً وتعليلاً لها.', NULL, 'ad160816-2026-4c00-9d00-160820260001', 'e1a81603-0003-4a03-b003-c0ffee000003', 'زاد استهلاك الطاقة بشكل كبير حيث يستخدمها الإنسان في مجالات كثيرة كالصناعة والزراعة، ومصادر الطاقة مثل النفط والغاز والمياه والرياح ليست كافية، لذلك اتجه العلماء إلى البحث عن مصادر جديدة للطاقة مثل الطاقة الحرارية والطاقة الشمسية التي يزخر بها الكون.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'معنى (يزخر) في قوله «التي يزخر بها الكون»:', '["يمتلئ", "يكثر", "يعلو", "يتوهج"]'::jsonb, 0, 'زخر البحر: امتلأ وفاض، فالمعنى أن الكون ممتلئ بهذه الطاقات. وهي أدق من «يكثر» لأنها تفيد الامتلاء والفيض معاً.', NULL, 'ad160816-2026-4c00-9d00-160820260001', 'e1a81603-0003-4a03-b003-c0ffee000003', 'زاد استهلاك الطاقة بشكل كبير حيث يستخدمها الإنسان في مجالات كثيرة كالصناعة والزراعة، ومصادر الطاقة مثل النفط والغاز والمياه والرياح ليست كافية، لذلك اتجه العلماء إلى البحث عن مصادر جديدة للطاقة مثل الطاقة الحرارية والطاقة الشمسية التي يزخر بها الكون.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'الشخص الذي يُقصد بعبارة «يبذل غاية جهده للمساواة مع أقرانه فقط»:', '["المقلد", "المجتهد", "صاحب الهمة الكبيرة", "المتفائل"]'::jsonb, 0, 'من يجعل غايته القصوى مشابهة أقرانه فهو يقلدهم ولا يسعى لتجاوزهم، وهذا وصف صاحب الهمة المتوسطة المتبع للنمطية.', NULL, 'ad160816-2026-4c00-9d00-160820260001', 'e1a81604-0004-4a04-b004-c0ffee000004', 'تختلف طموحات الناس وهممهم؛ فالأول هو صاحب الهمة الصغيرة، وهو الذي يتكئ على الناس ولا يهمه إلا اللهو، ولا يحب أن يفعل شيئاً أو ينجز شيئاً. والثاني صاحب الهمة المتوسطة، وهو شخص يتبع النمطية ويبذل غاية جهده للمساواة مع أقرانه فقط، فأكبر همه أن يشابه أقرانه. والثالث صاحب الهمة الكبيرة، تجده يلازم الناجحين ويحب أن يكون معهم ويتعلم منهم، وينجز المهام ويهتم بوقته ويحسن استغلاله، ويبتكر أشياء جديدة ويحطم الحواجز ويحقق نجاحه بنفسه.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'الضمير في (تجده) يعود على:', '["صاحب الهمة الكبيرة", "صاحب الهمة الصغيرة", "الناجح", "الفاشل"]'::jsonb, 0, '«والثالث صاحب الهمة الكبيرة تجده يلازم الناجحين» — الضمير عائد على الثالث المذكور قبله مباشرة.', NULL, 'ad160816-2026-4c00-9d00-160820260001', 'e1a81604-0004-4a04-b004-c0ffee000004', 'تختلف طموحات الناس وهممهم؛ فالأول هو صاحب الهمة الصغيرة، وهو الذي يتكئ على الناس ولا يهمه إلا اللهو، ولا يحب أن يفعل شيئاً أو ينجز شيئاً. والثاني صاحب الهمة المتوسطة، وهو شخص يتبع النمطية ويبذل غاية جهده للمساواة مع أقرانه فقط، فأكبر همه أن يشابه أقرانه. والثالث صاحب الهمة الكبيرة، تجده يلازم الناجحين ويحب أن يكون معهم ويتعلم منهم، وينجز المهام ويهتم بوقته ويحسن استغلاله، ويبتكر أشياء جديدة ويحطم الحواجز ويحقق نجاحه بنفسه.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'أنسب عنوان للنص:', '["أنواع الهمم", "أساليب النجاح", "شحذ الهمم", "صفات الناجحين"]'::jsonb, 0, 'النص قسّم الناس ثلاثة أصناف بحسب هممهم، فالعنوان الجامع لأفكاره كلها هو أنواع الهمم. أما صفات الناجحين فتغطي الصنف الثالث وحده.', NULL, 'ad160816-2026-4c00-9d00-160820260001', 'e1a81604-0004-4a04-b004-c0ffee000004', 'تختلف طموحات الناس وهممهم؛ فالأول هو صاحب الهمة الصغيرة، وهو الذي يتكئ على الناس ولا يهمه إلا اللهو، ولا يحب أن يفعل شيئاً أو ينجز شيئاً. والثاني صاحب الهمة المتوسطة، وهو شخص يتبع النمطية ويبذل غاية جهده للمساواة مع أقرانه فقط، فأكبر همه أن يشابه أقرانه. والثالث صاحب الهمة الكبيرة، تجده يلازم الناجحين ويحب أن يكون معهم ويتعلم منهم، وينجز المهام ويهتم بوقته ويحسن استغلاله، ويبتكر أشياء جديدة ويحطم الحواجز ويحقق نجاحه بنفسه.', 3, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'نفهم من النص أن التعب مرتبط بـ:', '["النجاح", "الفشل", "اللهو", "الراحة"]'::jsonb, 0, 'صاحب الهمة الكبيرة ينجز ويبتكر ويحطم الحواجز ليحقق نجاحه بنفسه — فالنجاح ثمرة الجهد والتعب، بعكس صاحب الهمة الصغيرة الذي يؤثر اللهو والدعة.', NULL, 'ad160816-2026-4c00-9d00-160820260001', 'e1a81604-0004-4a04-b004-c0ffee000004', 'تختلف طموحات الناس وهممهم؛ فالأول هو صاحب الهمة الصغيرة، وهو الذي يتكئ على الناس ولا يهمه إلا اللهو، ولا يحب أن يفعل شيئاً أو ينجز شيئاً. والثاني صاحب الهمة المتوسطة، وهو شخص يتبع النمطية ويبذل غاية جهده للمساواة مع أقرانه فقط، فأكبر همه أن يشابه أقرانه. والثالث صاحب الهمة الكبيرة، تجده يلازم الناجحين ويحب أن يكون معهم ويتعلم منهم، وينجز المهام ويهتم بوقته ويحسن استغلاله، ويبتكر أشياء جديدة ويحطم الحواجز ويحقق نجاحه بنفسه.', 4, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'أي مما يلي صحيح وفق النص؟', '["الناجح هو الذي يرسم أهدافه ويحققها بنفسه", "صاحب الهمة المتوسطة يبتكر أشياء جديدة", "الناجح يقلد الناجحين في كل شيء", "صاحب الهمة الصغيرة يحسن استغلال وقته"]'::jsonb, 0, 'النص يصف صاحب الهمة الكبيرة بأنه «يحقق نجاحه بنفسه». أما المتوسط فيتبع النمطية ولا يبتكر، والكبير يتعلم من الناجحين ولا يقلدهم، والصغير لا يهمه إلا اللهو.', NULL, 'ad160816-2026-4c00-9d00-160820260001', 'e1a81604-0004-4a04-b004-c0ffee000004', 'تختلف طموحات الناس وهممهم؛ فالأول هو صاحب الهمة الصغيرة، وهو الذي يتكئ على الناس ولا يهمه إلا اللهو، ولا يحب أن يفعل شيئاً أو ينجز شيئاً. والثاني صاحب الهمة المتوسطة، وهو شخص يتبع النمطية ويبذل غاية جهده للمساواة مع أقرانه فقط، فأكبر همه أن يشابه أقرانه. والثالث صاحب الهمة الكبيرة، تجده يلازم الناجحين ويحب أن يكون معهم ويتعلم منهم، وينجز المهام ويهتم بوقته ويحسن استغلاله، ويبتكر أشياء جديدة ويحطم الحواجز ويحقق نجاحه بنفسه.', 5, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'جملة «ليس بتجاهل المخاطر ولا بنسف الطموحات» جاءت لـ:', '["تصحيح مفهوم", "نفي فكرة", "استقراء حال", "بيان حال"]'::jsonb, 0, 'النص يصحح فهماً خاطئاً للتفاؤل: ينفي عنه ما ليس منه ثم يثبت حقيقته (حسن الظن بالله)، والنفي هنا وسيلة التصحيح لا غاية بذاتها.', NULL, 'ad160816-2026-4c00-9d00-160820260001', 'e1a81605-0005-4a05-b005-c0ffee000005', 'التفاؤل ليس دعوة لإنكار الواقع بتجاهل المخاطر، ولا بنسف الطموحات والاحتمالات، ولكنه حسن الظن بالله، والوعي والنظر في الاحتمالات الممكنة وتوقع الأفضل منها.', 1, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'تدعو القطعة إلى:', '["حسن الظن بالله", "تجاهل المخاطر", "نسف الطموحات", "إنكار الواقع"]'::jsonb, 0, '«ولكنه حسن الظن بالله» هي خلاصة القطعة ودعوتها، أما الخيارات الأخرى فمنفية في النص صراحة.', NULL, 'ad160816-2026-4c00-9d00-160820260001', 'e1a81605-0005-4a05-b005-c0ffee000005', 'التفاؤل ليس دعوة لإنكار الواقع بتجاهل المخاطر، ولا بنسف الطموحات والاحتمالات، ولكنه حسن الظن بالله، والوعي والنظر في الاحتمالات الممكنة وتوقع الأفضل منها.', 2, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'الضمير في كلمة (منها) يعود على:', '["الاحتمالات الممكنة", "الأفضل", "الطموحات", "المخاطر"]'::jsonb, 0, '«النظر في الاحتمالات الممكنة وتوقع الأفضل منها» أي توقع أفضل تلك الاحتمالات — فالضمير عائد عليها.', NULL, 'ad160816-2026-4c00-9d00-160820260001', 'e1a81605-0005-4a05-b005-c0ffee000005', 'التفاؤل ليس دعوة لإنكار الواقع بتجاهل المخاطر، ولا بنسف الطموحات والاحتمالات، ولكنه حسن الظن بالله، والوعي والنظر في الاحتمالات الممكنة وتوقع الأفضل منها.', 3, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'معنى (نسف) في قوله «نسف الطموحات»:', '["هدم", "وقع", "أهمل", "أجّل"]'::jsonb, 0, 'النسف هو الهدم والإزالة من الأساس، ومنه نسف البناء إذا هدمه بالكامل.', NULL, 'ad160816-2026-4c00-9d00-160820260001', 'e1a81605-0005-4a05-b005-c0ffee000005', 'التفاؤل ليس دعوة لإنكار الواقع بتجاهل المخاطر، ولا بنسف الطموحات والاحتمالات، ولكنه حسن الظن بالله، والوعي والنظر في الاحتمالات الممكنة وتوقع الأفضل منها.', 4, 'active', false);
  INSERT INTO questions (section, subject, topic, question_type, question_text, choices, correct_index, explanation, image_url, leak_group_id, passage_id, passage_text, passage_order, status, disabled)
  VALUES ('verbal', NULL, 'استيعاب المقروء', 'اختيار من متعدد', 'الفكرة التي لم ترد في القطعة:', '["التفاؤل هو استبعاد الحلول المستحيلة", "تجاهل الأخطار خطأ", "نسف الاحتمالات أمر مرفوض", "حسن الظن بالله أساس التفاؤل"]'::jsonb, 0, 'القطعة عرّفت التفاؤل بحسن الظن والنظر في الاحتمالات الممكنة، ولم تُعرّفه باستبعاد المستحيلة. أما بقية الأفكار فوردت نصاً أو نفياً صريحاً.', NULL, 'ad160816-2026-4c00-9d00-160820260001', 'e1a81605-0005-4a05-b005-c0ffee000005', 'التفاؤل ليس دعوة لإنكار الواقع بتجاهل المخاطر، ولا بنسف الطموحات والاحتمالات، ولكنه حسن الظن بالله، والوعي والنظر في الاحتمالات الممكنة وتوقع الأفضل منها.', 5, 'active', false);
END IF;
